module pulse_detect #(
    parameter s0 = 2'b00,
    parameter s1 = 2'b01,
    parameter s2 = 2'b10,
    parameter s3 = 2'b11
) (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state;
reg [1:0] next_state;

always@(posedge clk or negedge rst_n) 
begin
	if(~rst_n) state <= s0; else state <= next_state;
end

always@(*) 
begin
	case(state)
		s0:	next_state <= data_in ? s0 : s1;
		s1:	next_state <= data_in ? s2 : s1;
		s2:	begin
			if(data_in == 0)	next_state <= s3;
			else				next_state <= s0;
		end
		s3:	next_state <= data_in ? s2 : s1;
		default:	next_state <= s0;
	endcase
end

always@(*)
	data_out <= (state == s2) && (data_in == 0);

endmodule
